import{_ as a,o as n,c as o,a2 as t}from"./chunks/framework.DnrXFDHb.js";const h=JSON.parse('{"title":"Balance and Billing","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/billing.md","filePath":"en/guide/billing.md"}'),r={name:"en/guide/billing.md"};function i(l,e,c,s,u,d){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="balance-and-billing" tabindex="-1">Balance and Billing <a class="header-anchor" href="#balance-and-billing" aria-label="Permalink to &quot;Balance and Billing&quot;">​</a></h1><p>OpenRussiaRouter uses a unified prepaid billing system in <strong>US Dollars (USD)</strong>.</p><h2 id="how-charging-works" tabindex="-1">How Charging Works <a class="header-anchor" href="#how-charging-works" aria-label="Permalink to &quot;How Charging Works&quot;">​</a></h2><p>Funds are deducted automatically after each successful request to a model based on actual Token Usage.</p><p>Cost calculation formula:</p><p><code>Cost = (InputTokens * InputPrice + OutputTokens * OutputPrice + CacheTokens * CachePrice) / 1,000,000</code></p><h3 id="token-accounting-details" tabindex="-1">Token Accounting Details <a class="header-anchor" href="#token-accounting-details" aria-label="Permalink to &quot;Token Accounting Details&quot;">​</a></h3><ul><li><strong>Caching:</strong> If the model supports caching (e.g., Anthropic Prompt Caching), tokens that hit the cache are billed at a special (usually discounted) <code>CachePrice</code>. These tokens are subtracted from total <code>InputTokens</code> when calculating the base price cost.</li><li><strong>Rounding:</strong> Rounding is done to 6 decimal places (microcents).</li></ul><h2 id="topping-up-balance" tabindex="-1">Topping Up Balance <a class="header-anchor" href="#topping-up-balance" aria-label="Permalink to &quot;Topping Up Balance&quot;">​</a></h2><p>You can top up your balance via the dashboard. We use Rollypay to process payments. Conversion to USD happens at the current exchange rate at the time of crediting.</p><p>In the dashboard, you can choose a convenient Display Currency, for example, rubles (RUB) or euros (EUR) — the recalculation happens automatically using current exchange rates.</p><h2 id="zero-balance-errors" tabindex="-1">Zero Balance Errors <a class="header-anchor" href="#zero-balance-errors" aria-label="Permalink to &quot;Zero Balance Errors&quot;">​</a></h2><p>If your balance drops below zero, the API will start returning an <code>insufficient_balance</code> error (HTTP 402 / 400). <em>Exception:</em> If you are using a completely free model (price of all tokens = $0.00), requests will go through even with a negative balance.</p>',13)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
